import EOFCore
import Foundation
import SwiftUI

/// File and folder icons from the Material Icon Theme (the set the "Material Icons for GitHub"
/// extension uses), resolved the way VS Code does: exact file name, then the longest matching
/// extension, then the language, then a plain file icon. Generated by `Tools/material-icons.py`.
enum MaterialIcons {
    private struct Manifest: Decodable {
        let fileExtensions: [String: String]
        let fileNames: [String: String]
        let folderNames: [String: String]
        let languageIds: [String: String]
    }

    private static let manifest: Manifest? = {
        guard let url = Bundle.main.url(forResource: "material-icons", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(Manifest.self, from: data)
    }()

    /// EOF language ids that differ from VS Code's.
    private static let vscodeLanguage: [String: String] = [
        "shell": "shellscript", "objc": "objective-c", "plain": "plaintext", "gitignore": "ignore",
        "batch": "bat", "tex": "latex", "protobuf": "proto", "csv": "csv",
    ]

    private static var cache: [String: String] = [:]
    private static let lock = NSLock()

    /// The asset name for a file called `name`.
    static func file(_ name: String) -> String {
        let key = name.lowercased()
        lock.lock()
        defer { lock.unlock() }
        if let hit = cache[key] { return hit }
        let icon = resolve(key)
        cache[key] = icon
        return icon
    }

    private static func resolve(_ name: String) -> String {
        guard let manifest else { return "mi-file" }
        if let icon = manifest.fileNames[name] { return "mi-" + icon }
        // "a.test.ts" tries "test.ts" before "ts".
        var rest = Substring(name)
        while let dot = rest.firstIndex(of: ".") {
            rest = rest[rest.index(after: dot)...]
            if let icon = manifest.fileExtensions[String(rest)] { return "mi-" + icon }
        }
        let language = Languages.detect(filename: name)
        if language.id != Languages.plain.id {
            let id = vscodeLanguage[language.id] ?? language.id
            if let icon = manifest.languageIds[id] { return "mi-" + icon }
        }
        return "mi-file"
    }

    /// The asset name for a folder called `name` (`src`, `docs`, `.github`…).
    static func folder(_ name: String) -> String {
        manifest?.folderNames[name.lowercased()].map { "mi-" + $0 } ?? "mi-folder"
    }

    static func image(forFile name: String, isFolder: Bool = false) -> Image {
        Image(isFolder ? folder(name) : file(name))
    }
}
